let file = """{"version":3,"file":"SignInContent-CN3SVZOz.js","names":["$emit","$t"],"sources":["../../../../../../../../assets/images/comfy-logo-mono.svg","../../src/utils/hostWhitelist.ts","../../src/components/dialog/content/signin/ApiKeyForm.vue","../../src/components/dialog/content/signin/ApiKeyForm.vue","../../src/components/dialog/content/signin/SignInForm.vue","../../src/components/dialog/content/signin/SignInForm.vue","../../src/components/dialog/content/SignInContent.vue","../../src/components/dialog/content/SignInContent.vue"],"sourcesContent":["export default \"__VITE_PUBLIC_ASSET__cc1d62b1__\"","/**\n * Whitelisting helper for enabling SSO on safe, local-only hosts.\n *\n * Built-ins (always allowed):\n *   • 'localhost' and any subdomain of '.localhost' (e.g., app.localhost)\n *   • IPv4 loopback 127.0.0.0/8 (e.g., 127.0.0.1, 127.1.2.3)\n *   • IPv6 loopback ::1 (supports compressed/expanded textual forms)\n *\n * No environment variables are used. To add more exact hostnames,\n * edit HOST_WHITELIST below.\n */\n\nconst HOST_WHITELIST: string[] = ['localhost']\n\n/** Normalize for comparison: lowercase, strip port/brackets, trim trailing dot. */\nexport function normalizeHost(input: string): string {\n  let h = (input || '').trim().toLowerCase()\n\n  // Trim a trailing dot: 'localhost.' -> 'localhost'\n  h = h.replace(/\\.$/, '')\n\n  // Remove ':port' safely.\n  // Case 1: [IPv6]:port\n  const mBracket = h.match(/^\\[([^\\]]+)\\]:(\\d+)$/)\n  if (mBracket) {\n    h = mBracket[1] // keep only the host inside the brackets\n  } else {\n    // Case 2: hostname/IPv4:port (exactly one ':')\n    const mPort = h.match(/^([^:]+):(\\d+)$/)\n    if (mPort) h = mPort[1]\n  }\n\n  // Strip any remaining brackets (e.g., '[::1]' -> '::1')\n  h = h.replace(/^\\[|\\]$/g, '')\n\n  return h\n}\n\n/** Public check used by the UI. */\nexport function isHostWhitelisted(rawHost: string): boolean {\n  const host = normalizeHost(rawHost)\n  if (isLocalhostLabel(host)) return true\n  if (isIPv4Loopback(host)) return true\n  if (isIPv6Loopback(host)) return true\n  if (isComfyOrgHost(host)) return true\n  const normalizedList = HOST_WHITELIST.map(normalizeHost)\n  return normalizedList.includes(host)\n}\n\n/* -------------------- Helpers -------------------- */\n\nfunction isLocalhostLabel(h: string): boolean {\n  // 'localhost' and any subdomain (e.g., 'app.localhost')\n  return h === 'localhost' || h.endsWith('.localhost')\n}\n\nconst IPV4_OCTET = '(?:25[0-5]|2[0-4]\\\\d|1\\\\d\\\\d|0?\\\\d?\\\\d)'\nconst V4_LOOPBACK_RE = new RegExp(\n  '^127\\\\.' + IPV4_OCTET + '\\\\.' + IPV4_OCTET + '\\\\.' + IPV4_OCTET + '$'\n)\n\nfunction isIPv4Loopback(h: string): boolean {\n  // 127/8 with strict 0–255 octets (leading zeros allowed, e.g., 127.000.000.001)\n  return V4_LOOPBACK_RE.test(h)\n}\n\n// Fully expanded IPv6 loopback: 0:0:0:0:0:0:0:1 (allow leading zeros up to 4 chars)\nconst V6_FULL_LOOPBACK_RE = /^(?:0{1,4}:){7}0{0,3}1$/i\n\n// Compressed IPv6 loopback forms around '::' with only zero groups before the final :1\n// - Left side: zero groups separated by ':' (no trailing colon required)\n// - Right side: zero groups each followed by ':' (so the final ':1' is provided by the pattern)\n// The final group is exactly value 1, with up to 3 leading zeros (e.g., '0001').\nconst V6_COMPRESSED_LOOPBACK_RE =\n  /^((?:0{1,4}(?::0{1,4}){0,6})?)::((?:0{1,4}:){0,6})0{0,3}1$/i\n\nfunction isIPv6Loopback(h: string): boolean {\n  // Exact full form: 0:0:0:0:0:0:0:1 (with up to 3 leading zeros on the final \"1\" group)\n  if (V6_FULL_LOOPBACK_RE.test(h)) return true\n\n  // Compressed forms that still equal ::1 (e.g., ::1, ::0001, 0:0::1, ::0:1, etc.)\n  const m = h.match(V6_COMPRESSED_LOOPBACK_RE)\n  if (!m) return false\n\n  // Count explicit zero groups on each side of '::' to ensure at least one group is compressed.\n  // (leftCount + rightCount) must be ≤ 6 so that the total expanded groups = 8.\n  const leftCount = m[1] ? (m[1].match(/0{1,4}:/gi)?.length ?? 0) : 0\n  const rightCount = m[2] ? (m[2].match(/0{1,4}:/gi)?.length ?? 0) : 0\n\n  // Require that at least one group was actually compressed: i.e., leftCount + rightCount ≤ 6.\n  return leftCount + rightCount <= 6\n}\n\nconst COMFY_ORG_HOST = /\\.comfy\\.org$/\n\nfunction isComfyOrgHost(h: string): boolean {\n  return COMFY_ORG_HOST.test(h)\n}\n","<template>\n  <div class=\"flex flex-col gap-6\">\n    <div class=\"mb-8 flex flex-col gap-4\">\n      <h1 class=\"my-0 text-2xl/normal font-medium\">\n        {{ t('auth.apiKey.title') }}\n      </h1>\n      <p class=\"my-0 text-base text-muted-foreground\">\n        {{ t('auth.apiKey.description') }}\n        <a\n          href=\"https://docs.comfy.org/interface/user#logging-in-with-an-api-key\"\n          target=\"_blank\"\n          class=\"underline underline-offset-4 hover:text-base-foreground\"\n        >\n          {{ t('g.learnMore') }}\n        </a>\n      </p>\n    </div>\n\n    <form class=\"flex flex-col gap-6\" @submit.prevent=\"onSubmit\">\n      <VeeField v-slot=\"{ componentField, errors }\" name=\"apiKey\">\n        <Field :data-invalid=\"!!errors.length\">\n          <FieldLabel for=\"comfy-org-api-key\">\n            {{ t('auth.apiKey.label') }}\n          </FieldLabel>\n          <Input\n            v-bind=\"componentField\"\n            id=\"comfy-org-api-key\"\n            autocomplete=\"off\"\n            type=\"password\"\n            :placeholder=\"t('auth.apiKey.placeholder')\"\n            :aria-invalid=\"!!errors.length\"\n          />\n          <FieldDescription>\n            {{ t('auth.apiKey.helpText') }}\n            <a :href=\"`${comfyPlatformBaseUrl}/login`\" target=\"_blank\">\n              {{ t('auth.apiKey.generateKey') }}\n            </a>\n            <span class=\"mx-1\">•</span>\n            <a\n              href=\"https://docs.comfy.org/tutorials/partner-nodes/overview#log-in-with-comfyui-account-api-key-on-non-whitelisted-websites\"\n              target=\"_blank\"\n            >\n              {{ t('auth.apiKey.whitelistInfo') }}\n            </a>\n          </FieldDescription>\n          <FieldError v-if=\"errors.length\" :errors />\n        </Field>\n      </VeeField>\n\n      <div class=\"mt-4 flex items-center justify-between\">\n        <Button type=\"button\" variant=\"textonly\" @click=\"$emit('back')\">\n          {{ t('g.back') }}\n        </Button>\n        <Button\n          type=\"submit\"\n          variant=\"primary\"\n          :loading=\"loading\"\n          :disabled=\"loading\"\n        >\n          {{ t('g.save') }}\n        </Button>\n      </div>\n    </form>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { Field as VeeField, useForm } from 'vee-validate'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Field from '@/components/ui/field/Field.vue'\nimport FieldDescription from '@/components/ui/field/FieldDescription.vue'\nimport FieldError from '@/components/ui/field/FieldError.vue'\nimport FieldLabel from '@/components/ui/field/FieldLabel.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport { getComfyPlatformBaseUrl } from '@/config/comfyApi'\nimport {\n  configValueOrDefault,\n  remoteConfig\n} from '@/platform/remoteConfig/remoteConfig'\nimport { apiKeySchema } from '@/schemas/signInSchema'\nimport { useApiKeyAuthStore } from '@/stores/apiKeyAuthStore'\nimport { useAuthStore } from '@/stores/authStore'\nimport { toTypedSchema } from '@/utils/zodTypedSchema'\n\nconst authStore = useAuthStore()\nconst apiKeyStore = useApiKeyAuthStore()\nconst loading = computed(() => authStore.loading)\nconst comfyPlatformBaseUrl = computed(() =>\n  configValueOrDefault(\n    remoteConfig.value,\n    'comfy_platform_base_url',\n    getComfyPlatformBaseUrl()\n  )\n)\n\nconst { t } = useI18n()\n\nconst emit = defineEmits<{\n  (e: 'back'): void\n  (e: 'success'): void\n}>()\n\nconst { handleSubmit } = useForm({\n  validationSchema: toTypedSchema(apiKeySchema),\n  initialValues: { apiKey: '' }\n})\n\nconst onSubmit = handleSubmit(async ({ apiKey }) => {\n  await apiKeyStore.storeApiKey(apiKey)\n  emit('success')\n})\n</script>\n","<template>\n  <div class=\"flex flex-col gap-6\">\n    <div class=\"mb-8 flex flex-col gap-4\">\n      <h1 class=\"my-0 text-2xl/normal font-medium\">\n        {{ t('auth.apiKey.title') }}\n      </h1>\n      <p class=\"my-0 text-base text-muted-foreground\">\n        {{ t('auth.apiKey.description') }}\n        <a\n          href=\"https://docs.comfy.org/interface/user#logging-in-with-an-api-key\"\n          target=\"_blank\"\n          class=\"underline underline-offset-4 hover:text-base-foreground\"\n        >\n          {{ t('g.learnMore') }}\n        </a>\n      </p>\n    </div>\n\n    <form class=\"flex flex-col gap-6\" @submit.prevent=\"onSubmit\">\n      <VeeField v-slot=\"{ componentField, errors }\" name=\"apiKey\">\n        <Field :data-invalid=\"!!errors.length\">\n          <FieldLabel for=\"comfy-org-api-key\">\n            {{ t('auth.apiKey.label') }}\n          </FieldLabel>\n          <Input\n            v-bind=\"componentField\"\n            id=\"comfy-org-api-key\"\n            autocomplete=\"off\"\n            type=\"password\"\n            :placeholder=\"t('auth.apiKey.placeholder')\"\n            :aria-invalid=\"!!errors.length\"\n          />\n          <FieldDescription>\n            {{ t('auth.apiKey.helpText') }}\n            <a :href=\"`${comfyPlatformBaseUrl}/login`\" target=\"_blank\">\n              {{ t('auth.apiKey.generateKey') }}\n            </a>\n            <span class=\"mx-1\">•</span>\n            <a\n              href=\"https://docs.comfy.org/tutorials/partner-nodes/overview#log-in-with-comfyui-account-api-key-on-non-whitelisted-websites\"\n              target=\"_blank\"\n            >\n              {{ t('auth.apiKey.whitelistInfo') }}\n            </a>\n          </FieldDescription>\n          <FieldError v-if=\"errors.length\" :errors />\n        </Field>\n      </VeeField>\n\n      <div class=\"mt-4 flex items-center justify-between\">\n        <Button type=\"button\" variant=\"textonly\" @click=\"$emit('back')\">\n          {{ t('g.back') }}\n        </Button>\n        <Button\n          type=\"submit\"\n          variant=\"primary\"\n          :loading=\"loading\"\n          :disabled=\"loading\"\n        >\n          {{ t('g.save') }}\n        </Button>\n      </div>\n    </form>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { Field as VeeField, useForm } from 'vee-validate'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Field from '@/components/ui/field/Field.vue'\nimport FieldDescription from '@/components/ui/field/FieldDescription.vue'\nimport FieldError from '@/components/ui/field/FieldError.vue'\nimport FieldLabel from '@/components/ui/field/FieldLabel.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport { getComfyPlatformBaseUrl } from '@/config/comfyApi'\nimport {\n  configValueOrDefault,\n  remoteConfig\n} from '@/platform/remoteConfig/remoteConfig'\nimport { apiKeySchema } from '@/schemas/signInSchema'\nimport { useApiKeyAuthStore } from '@/stores/apiKeyAuthStore'\nimport { useAuthStore } from '@/stores/authStore'\nimport { toTypedSchema } from '@/utils/zodTypedSchema'\n\nconst authStore = useAuthStore()\nconst apiKeyStore = useApiKeyAuthStore()\nconst loading = computed(() => authStore.loading)\nconst comfyPlatformBaseUrl = computed(() =>\n  configValueOrDefault(\n    remoteConfig.value,\n    'comfy_platform_base_url',\n    getComfyPlatformBaseUrl()\n  )\n)\n\nconst { t } = useI18n()\n\nconst emit = defineEmits<{\n  (e: 'back'): void\n  (e: 'success'): void\n}>()\n\nconst { handleSubmit } = useForm({\n  validationSchema: toTypedSchema(apiKeySchema),\n  initialValues: { apiKey: '' }\n})\n\nconst onSubmit = handleSubmit(async ({ apiKey }) => {\n  await apiKeyStore.storeApiKey(apiKey)\n  emit('success')\n})\n</script>\n","<template>\n  <form class=\"flex flex-col gap-10\" @submit.prevent=\"onSubmit\">\n    <FieldGroup>\n      <VeeField v-slot=\"{ componentField, errors }\" name=\"email\">\n        <Field :data-invalid=\"!!errors.length\">\n          <FieldLabel :for=\"emailInputId\">\n            {{ t('auth.login.emailLabel') }}\n          </FieldLabel>\n          <Input\n            v-bind=\"componentField\"\n            :id=\"emailInputId\"\n            autocomplete=\"email\"\n            type=\"text\"\n            :placeholder=\"t('auth.login.emailPlaceholder')\"\n            :aria-invalid=\"!!errors.length\"\n          />\n          <FieldError v-if=\"errors.length\" :errors />\n        </Field>\n      </VeeField>\n\n      <VeeField v-slot=\"{ componentField, errors }\" name=\"password\">\n        <Field :data-invalid=\"!!errors.length\">\n          <div class=\"flex items-center justify-between\">\n            <FieldLabel for=\"comfy-org-sign-in-password\">\n              {{ t('auth.login.passwordLabel') }}\n            </FieldLabel>\n            <Button\n              type=\"button\"\n              variant=\"link\"\n              size=\"unset\"\n              :class=\"\n                cn(\n                  'p-0 select-none',\n                  !canResetPassword && 'cursor-not-allowed opacity-50'\n                )\n              \"\n              @click=\"handleForgotPassword\"\n            >\n              {{ t('auth.login.forgotPassword') }}\n            </Button>\n          </div>\n          <PasswordInput\n            v-bind=\"componentField\"\n            id=\"comfy-org-sign-in-password\"\n            autocomplete=\"current-password\"\n            :placeholder=\"t('auth.login.passwordPlaceholder')\"\n            :aria-invalid=\"!!errors.length\"\n          />\n          <FieldError v-if=\"errors.length\" :errors />\n        </Field>\n      </VeeField>\n    </FieldGroup>\n\n    <Spinner v-if=\"loading\" class=\"mx-auto size-8\" />\n    <Button\n      v-else\n      type=\"submit\"\n      class=\"h-10 font-medium\"\n      :disabled=\"!meta.valid\"\n    >\n      {{ t('auth.login.loginButton') }}\n    </Button>\n  </form>\n</template>\n\n<script setup lang=\"ts\">\nimport { useThrottleFn } from '@vueuse/core'\nimport { Field as VeeField, useForm, useIsFieldValid } from 'vee-validate'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Field from '@/components/ui/field/Field.vue'\nimport FieldError from '@/components/ui/field/FieldError.vue'\nimport FieldGroup from '@/components/ui/field/FieldGroup.vue'\nimport FieldLabel from '@/components/ui/field/FieldLabel.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport PasswordInput from '@/components/ui/input/PasswordInput.vue'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport { signInSchema } from '@/schemas/signInSchema'\nimport type { SignInData } from '@/schemas/signInSchema'\nimport { useAuthStore } from '@/stores/authStore'\nimport { toTypedSchema } from '@/utils/zodTypedSchema'\n\nconst authStore = useAuthStore()\nconst authActions = useAuthActions()\nconst loading = computed(() => authStore.loading)\n\nconst { t } = useI18n()\n\nconst emit = defineEmits<{\n  submit: [values: SignInData]\n}>()\n\nconst emailInputId = 'comfy-org-sign-in-email'\n\nconst { handleSubmit, meta, validateField, values } = useForm({\n  validationSchema: toTypedSchema(signInSchema),\n  initialValues: { email: '', password: '' }\n})\nconst isEmailValid = useIsFieldValid('email')\nconst canResetPassword = computed(() => !!values.email && isEmailValid.value)\n\nconst onSubmit = useThrottleFn(\n  handleSubmit((formValues) => emit('submit', formValues)),\n  1_500\n)\n\nasync function handleForgotPassword() {\n  const { valid } = await validateField('email')\n  const email = values.email\n  if (!valid || !email) {\n    document.getElementById(emailInputId)?.focus()\n    return\n  }\n  await authActions.sendPasswordReset(email)\n}\n</script>\n","<template>\n  <form class=\"flex flex-col gap-10\" @submit.prevent=\"onSubmit\">\n    <FieldGroup>\n      <VeeField v-slot=\"{ componentField, errors }\" name=\"email\">\n        <Field :data-invalid=\"!!errors.length\">\n          <FieldLabel :for=\"emailInputId\">\n            {{ t('auth.login.emailLabel') }}\n          </FieldLabel>\n          <Input\n            v-bind=\"componentField\"\n            :id=\"emailInputId\"\n            autocomplete=\"email\"\n            type=\"text\"\n            :placeholder=\"t('auth.login.emailPlaceholder')\"\n            :aria-invalid=\"!!errors.length\"\n          />\n          <FieldError v-if=\"errors.length\" :errors />\n        </Field>\n      </VeeField>\n\n      <VeeField v-slot=\"{ componentField, errors }\" name=\"password\">\n        <Field :data-invalid=\"!!errors.length\">\n          <div class=\"flex items-center justify-between\">\n            <FieldLabel for=\"comfy-org-sign-in-password\">\n              {{ t('auth.login.passwordLabel') }}\n            </FieldLabel>\n            <Button\n              type=\"button\"\n              variant=\"link\"\n              size=\"unset\"\n              :class=\"\n                cn(\n                  'p-0 select-none',\n                  !canResetPassword && 'cursor-not-allowed opacity-50'\n                )\n              \"\n              @click=\"handleForgotPassword\"\n            >\n              {{ t('auth.login.forgotPassword') }}\n            </Button>\n          </div>\n          <PasswordInput\n            v-bind=\"componentField\"\n            id=\"comfy-org-sign-in-password\"\n            autocomplete=\"current-password\"\n            :placeholder=\"t('auth.login.passwordPlaceholder')\"\n            :aria-invalid=\"!!errors.length\"\n          />\n          <FieldError v-if=\"errors.length\" :errors />\n        </Field>\n      </VeeField>\n    </FieldGroup>\n\n    <Spinner v-if=\"loading\" class=\"mx-auto size-8\" />\n    <Button\n      v-else\n      type=\"submit\"\n      class=\"h-10 font-medium\"\n      :disabled=\"!meta.valid\"\n    >\n      {{ t('auth.login.loginButton') }}\n    </Button>\n  </form>\n</template>\n\n<script setup lang=\"ts\">\nimport { useThrottleFn } from '@vueuse/core'\nimport { Field as VeeField, useForm, useIsFieldValid } from 'vee-validate'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Field from '@/components/ui/field/Field.vue'\nimport FieldError from '@/components/ui/field/FieldError.vue'\nimport FieldGroup from '@/components/ui/field/FieldGroup.vue'\nimport FieldLabel from '@/components/ui/field/FieldLabel.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport PasswordInput from '@/components/ui/input/PasswordInput.vue'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport { signInSchema } from '@/schemas/signInSchema'\nimport type { SignInData } from '@/schemas/signInSchema'\nimport { useAuthStore } from '@/stores/authStore'\nimport { toTypedSchema } from '@/utils/zodTypedSchema'\n\nconst authStore = useAuthStore()\nconst authActions = useAuthActions()\nconst loading = computed(() => authStore.loading)\n\nconst { t } = useI18n()\n\nconst emit = defineEmits<{\n  submit: [values: SignInData]\n}>()\n\nconst emailInputId = 'comfy-org-sign-in-email'\n\nconst { handleSubmit, meta, validateField, values } = useForm({\n  validationSchema: toTypedSchema(signInSchema),\n  initialValues: { email: '', password: '' }\n})\nconst isEmailValid = useIsFieldValid('email')\nconst canResetPassword = computed(() => !!values.email && isEmailValid.value)\